/* Export the monitor and the scanlines generated by the disc's G0 actors. */
#include <libretro.h>
#include <stdint.h>
static void report_video(const void *,unsigned,unsigned,size_t);
#define p_retro_set_video_refresh(cb) p_retro_set_video_refresh(report_video)
#include "runner.c"

enum { FIRST=13740, WIDTH=192, TOP=14, HEIGHT=132 };
static uint16_t background[256*224], rows[8192][WIDTH], slots[16384];
static unsigned used;
static void word(FILE *f,uint16_t value) { fputc(value>>8,f); fputc(value&255,f); }

static void report_video(const void *data,unsigned w,unsigned h,size_t pitch)
{
    video(data,w,h,pitch);
    if (frame+1<FIRST) return;
    if (w!=256 || h!=224 || !rgb) fail("Unexpected report video mode");
    static FILE *ids,*bank;
    static uint8_t levels[256];
    if (!ids) {
        for (unsigned c=0;c<256;c++) levels[c]=(c+17)/34*255/7*31/255;
        ids=fopen("ids.raw","wb");
        bank=fopen("rows.raw","wb");
        if (!ids || !bank) fail("Cannot write report rows");
    }
    FILE *base=frame+1==FIRST ? fopen("base.raw","wb") : NULL;
    if (frame+1==FIRST && !base) fail("Cannot write monitor");
    for (unsigned y=0;y<h;y++) {
        uint16_t line[WIDTH];
        uint32_t hash=2166136261u;
        for (unsigned x=0;x<w;x++) {
            const uint8_t *p=rgb+3*(y*w+x);
            uint16_t color=0x8000|levels[*p]|(levels[p[1]]<<5)|(levels[p[2]]<<10);
            if (base) { background[y*w+x]=color; word(base,color); }
            if (y>=TOP && y<TOP+HEIGHT && x>=32 && x<32+WIDTH) {
                line[x-32]=color;
                hash=(hash^color)*16777619u;
            } else if (background[y*w+x]!=color) fail("Report draw exceeds monitor window");
        }
        if (y<TOP || y>=TOP+HEIGHT) continue;
        unsigned slot=(hash^(hash>>16))&16383;
        while (slots[slot] && memcmp(rows[slots[slot]-1],line,sizeof(line))) slot=(slot+1)&16383;
        if (!slots[slot]) {
            if (used>=8192) fail("Report row dictionary overflow");
            memcpy(rows[used],line,sizeof(line)); slots[slot]=++used;
            for (unsigned i=0;i<WIDTH;i++) word(bank,line[i]);
        }
        word(ids,slots[slot]-1);
    }
    if (base) fclose(base);
}
